    var ADDS = [{"p":"PART 2. 개항과 불평등 조약","q":[{"answer":"O","text":"1883년에 개정된 조일 통상 장정에는 다른 나라에 준 혜택을 자동으로 함께 받는 최혜국 대우 조항이 새로 포함되었고, 흉년에 곡물 수출을 막을 수 있는 방곡령의 근거 규정도 담겼다.","exp":"1883년 개정 조일 통상 장정은 최혜국 대우와 방곡령 규정을 함께 담았다. 최혜국 대우가 강화도 조약에서 처음 규정되었다고 착각하기 쉬우나, 최혜국 대우는 1882년 조미 수호 통상 조약에서 처음 등장한 점과 구분한다.","src":"한능검 제67회"},{"answer":"X","text":"1883년에 개정된 조일 통상 장정에는 흉년에 곡물 수출을 막을 수 있는 방곡령의 근거 규정이 담겼으나, 다른 나라에 준 혜택을 함께 받는 최혜국 대우 조항은 끝내 포함되지 않았다.","exp":"뒷부분이 틀렸다. 1883년 개정 조일 통상 장정에는 방곡령 근거 규정뿐 아니라 최혜국 대우 조항도 함께 포함되었다. 최혜국 대우가 빠졌다는 서술이 사실과 다르다."}],"tb":[],"wi":["조일 통상 장정(1883 개정) = 최혜국 대우 조항·방곡령 근거 규정 포함 (최혜국 대우가 없다고 하면 ❌)"]},{"p":"PART 7. 개항기 경제·근대 문물·교육·언론","q":[{"answer":"O","text":"한성순보는 박문국에서 발간된 우리나라 최초의 근대 신문으로, 순 한문으로 열흘마다 발행하는 것을 원칙으로 하였다.","exp":"한성순보는 세계 정세를 전하고 개화 정책을 알린 관보 성격의 신문으로, 순 한문·열흘 간격 발행이 원칙이었다. 최초의 순한글 신문인 독립신문과 발행 문체를 구분해 기억한다.","src":"한능검 제67회"},{"answer":"X","text":"한성순보는 박문국에서 발간된 우리나라 최초의 근대 신문으로, 순 한문으로 날마다 발행하는 것을 원칙으로 하였다.","exp":"발행 주기가 틀렸다. 한성순보는 날마다가 아니라 열흘마다 발행하는 것이 원칙이었다. 박문국 발행·순 한문이라는 점은 옳다."}],"tb":[],"wi":[]},{"p":"PART 5. 독립 협회·대한제국·국권 피탈","q":[{"answer":"O","text":"박정양은 초대 주미 공사로 미국에 부임하여 대통령에게 고종의 국서를 전달하였고, 귀국한 뒤 미속습유를 지어 미국의 문물과 제도를 소개하였다.","exp":"박정양은 초대 주미 공사이자 미속습유의 저자로, 뒤에 관민 공동회에 참여해 독립 협회의 제안을 받아들여 중추원 관제 개편을 추진하였다. 조선책략(황준헌)과 저술을 혼동하지 않는다.","src":"한능검 제67회"},{"answer":"X","text":"박정양은 초대 주미 공사로 미국에 부임하여 대통령에게 고종의 국서를 전달하였고, 귀국한 뒤 조선책략을 지어 미국의 문물과 제도를 소개하였다.","exp":"저술이 틀렸다. 박정양이 귀국 후 지은 것은 미속습유이며, 조선책략은 청의 외교관 황준헌이 지어 김홍집이 들여온 책이다. 주미 공사·국서 전달은 옳다."}],"tb":[{"k":"p","t":"박정양은 초대 주미 공사로 미국에 부임해 대통령에게 고종의 국서를 전달하고, 귀국 후 미속습유를 지어 미국의 문물·제도를 소개하였다. 뒤에 관민 공동회에 참여하고 독립 협회의 제안을 받아들여 중추원 관제 개편을 추진하였다."}],"wi":["박정양 = 초대 주미 공사·미속습유 저술 (귀국 후 지은 책을 조선책략이라 하면 ❌ — 조선책략은 황준헌)"]},{"p":"PART 5. 독립 협회·대한제국·국권 피탈","q":[{"answer":"O","text":"대한제국은 광무개혁을 추진하면서 황제 직속의 원수부를 창설하여 황제의 군 통수권을 크게 강화하였다.","exp":"원수부는 대한국 국제에 명시된 황제의 군 통수권을 뒷받침한 기구이다. 제1차 갑오개혁 때의 군국기무처와 설치 시기·주체를 구분한다.","src":"한능검 제67회"},{"answer":"X","text":"대한제국은 광무개혁을 추진하면서 원수부를 창설하였으나, 이 기구는 의정부에 소속되어 군 통수권을 내각에 넘기기 위한 것이었다.","exp":"성격이 반대다. 원수부는 의정부 소속이 아니라 황제 직속 기구로, 군 통수권을 내각이 아닌 황제에게 집중시켰다. 원수부 창설 자체는 옳다."}],"tb":[],"wi":[]},{"p":"PART 7. 개항기 경제·근대 문물·교육·언론","q":[{"answer":"O","text":"백동화는 근대에 전환국에서 발행된 화폐로, 뒷날 메가타가 주도한 화폐 정리 사업을 거치며 등급에 따라 정리되었다.","exp":"백동화는 전환국에서 발행된 근대 화폐로, 화폐 정리 사업 때 갑·을·병종으로 나뉘어 차등 교환되었다. 발행처(전환국)와 정리 사업(메가타)을 함께 묶어 기억한다.","src":"한능검 제67회"},{"answer":"X","text":"백동화는 근대에 전환국에서 발행된 화폐로, 화폐 정리 사업 때 등급 구분 없이 모두 같은 값으로 새 화폐와 교환되어 상공업자에게 큰 이익을 주었다.","exp":"결과가 틀렸다. 화폐 정리 사업은 백동화를 갑·을·병종으로 나누어 차등 교환하였고, 등급이 낮은 화폐는 교환에서 손해를 봐 국내 상공업자가 큰 타격을 입었다. 전환국 발행은 옳다."}],"tb":[],"wi":["백동화 = 전환국 발행 화폐 (화폐 정리 사업 때 등급 없이 전액 교환되었다고 하면 ❌ — 갑·을·병종 차등 교환)"]}];
