    var ADDS = [{"p":"PART 6. 항일 의병과 애국 계몽 운동","q":[{"answer":"O","text":"13도 창의군은 고종의 강제 퇴위와 대한 제국 군대의 해산에 반발하여 각지의 의병 부대가 연합해 결성되었다.","exp":"13도 창의군은 고종 강제 퇴위와 군대 해산에 반발해 일어난 정미의병이 연합한 부대로, 이인영을 총대장, 허위를 군사장으로 삼아 서울 진공 작전을 폈다. 을미사변·단발령이 계기인 을미의병과 계기를 구분한다.","src":"한능검 제65회"},{"answer":"X","text":"13도 창의군은 명성 황후 시해와 단발령 시행에 반발하여 각지의 의병 부대가 연합해 결성되었다.","exp":"계기가 틀렸다. 13도 창의군은 정미의병의 연합 부대로 고종 강제 퇴위와 군대 해산에 반발해 결성되었다. 명성 황후 시해(을미사변)와 단발령은 을미의병의 계기이므로 앞 시기의 사건을 끌어온 함정이다."}],"tb":[],"wi":[]},{"p":"PART 5. 독립 협회·대한제국·국권 피탈","q":[{"answer":"O","text":"지금의 덕수궁 경내에 있는 중명전은 대한제국의 외교권을 빼앗은 을사늑약이 강제로 체결된 장소이다.","exp":"중명전은 덕수궁의 별관으로 1905년 을사늑약이 강제 체결된 곳이다. 이 조약으로 외교권이 박탈되고 통감부가 설치되었다. 황제 즉위식을 올린 환구단과 장소를 혼동하지 않도록 한다.","src":"한능검 제65회"},{"answer":"X","text":"지금의 덕수궁 경내에 있는 중명전은 대한제국의 군대 해산을 규정한 정미 7조약이 강제로 체결된 장소이다.","exp":"조약이 틀렸다. 중명전에서 강제로 체결된 것은 외교권을 빼앗은 을사늑약(1905)이다. 정미 7조약(1907)은 차관 정치와 군대 해산을 규정한 별개의 조약이므로 조약 이름과 내용이 뒤바뀌었다."}],"tb":[{"k":"p","t":"을사늑약(1905)은 덕수궁의 별관인 중명전에서 강제로 체결되었다. 이 조약으로 대한제국은 외교권을 빼앗기고 통감부가 설치되었다."}],"wi":["중명전 = 을사늑약(1905) 강제 체결 장소 (정미 7조약·한성 조약 등 다른 조약 체결지로 서술하면 ❌)"]},{"p":"PART 7. 개항기 경제·근대 문물·교육·언론","q":[{"answer":"O","text":"배재 학당과 이화 학당은 아펜젤러와 스크랜턴 등 개신교 선교사가 세운 사립 학교이다.","exp":"배재 학당(아펜젤러)과 이화 학당(스크랜턴)은 개신교 선교사가 세운 사립 학교로, 교육 입국 조서 이후 세워진 관립 학교와는 설립 주체가 다르다. 특히 이화 학당은 최초의 여성 교육 기관이라는 점을 함께 기억한다.","src":"한능검 제65회"},{"answer":"X","text":"배재 학당과 이화 학당은 정부가 교육 입국 조서에 따라 인재를 기르기 위해 세운 관립 학교이다.","exp":"설립 주체가 틀렸다. 배재·이화 학당은 개신교 선교사가 세운 사립 학교이다. 교육 입국 조서(1895) 이후 정부가 세운 관립 학교는 한성 사범 학교 등으로, 두 계열을 뒤바꾼 함정이다."}],"tb":[],"wi":[]}];
    for (var ai = 0; ai < ADDS.length; ai++) { insQ(ADDS[ai].p, ADDS[ai].q); insT(ADDS[ai].p, ADDS[ai].tb, ADDS[ai].wi); }
    var TAGS = [{"n":"독일 상인 오페르트가 통상을 강요하고자 충청도 덕산","l":"한능검 제65회"},{"n":"제물포 조약을 체결하여 일본 공사관에 경비병 주둔을 허용","l":"한능검 제65회"},{"n":"만석보를 쌓아 과중한 수세를 강제로 거두는 등 학정을 일삼자 전봉준","l":"한능검 제65회"},{"n":"헤이그 만국 평화 회의에 특사로 파견하여 조약의 부당함을 알리려","l":"한능검 제65회"},{"n":"대한국 국제를 반포한 황제는 고종이며","l":"한능검 제65회"},{"n":"황국 중앙 총상회를 조직하여 외국 상인의 상권 침탈에 맞서 상권 수호","l":"한능검 제65회"},{"n":"1907년 대구에서 김광제·서상돈 등의 발의로 일본에 진 나랏빚을 갚기 위한 국채 보상 운동","l":"한능검 제65회"},{"n":"보안회는 일제가 요구한 황무지 개간권에 반대하는 운동을 벌여 결국 이를 저지","l":"한능검 제65회"},{"n":"중추원을 개편하여 의회를 설립하려는 운동을 전개하였다","l":"한능검 제65회"},{"n":"전주성에서 정부와 전주 화약을 맺고 자진 해산한 뒤 전라도 각지에 집강소","l":"한능검 제65회"}];
